const postsContainer = document.getElementById("postsContainer");
const createPostForm = document.getElementById("createPostForm");
const linkButton = document.querySelector(".load-button");
const deletePostButton = document.querySelector(".deletePostButton");

let posts = [];      // Масив для збереження всіх постів із сервера
let currentIndex = 0; // Індекс поточного поста

// Завантажуємо всі пости з API (MockAPI не підтримує пагінацію за замовчуванням)
async function fetchPosts() {
    try {
        const response = await fetch("https://687cb0eb918b6422432f194e.mockapi.io/posts");
        posts = await response.json();
    } catch (error) {
        console.error("Помилка завантаження постів:", error);
    }
}

// Відобразити пост за currentIndex
function renderCurrentPost() {
    if (posts.length === 0) {
        postsContainer.innerHTML = "<p>Постів немає</p>";
        return;
    }
    const post = posts[currentIndex];
    postsContainer.innerHTML = `
        <div class="post" data-id="${post.id}">
            <h2>${post.title}</h2>
            <p>${post.content}</p>
        </div>
    `;
}

// Кнопка "Наступний пост"
linkButton.addEventListener("click", () => {
    if (posts.length === 0) return;
    if (currentIndex < posts.length - 1) {
        currentIndex++;
        renderCurrentPost();
    } else {
        alert("Це останній пост");
    }
});

// Видалення поточного поста
deletePostButton.addEventListener("click", async () => {
    if (posts.length === 0) return;

    const post = posts[currentIndex];
    try {
        const response = await fetch(`https://687cb0eb918b6422432f194e.mockapi.io/posts/${post.id}`, {
            method: "DELETE",
        });
        if (response.ok) {
            posts.splice(currentIndex, 1); // Видаляємо з локального масиву
            if (currentIndex > 0) {
                currentIndex--; // Переходимо до попереднього поста
            }
            renderCurrentPost();
        } else {
            alert("Не вдалося видалити пост");
        }
    } catch (error) {
        console.error("Помилка видалення:", error);
    }
});

// Створення нового поста
createPostForm.addEventListener("submit", async (e) => {
    e.preventDefault();
    const title = document.getElementById("titleInput").value.trim();
    const content = document.getElementById("contentInput").value.trim();
    if (!title || !content) return;

    try {
        const response = await fetch("https://687cb0eb918b6422432f194e.mockapi.io/posts", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ title, content }),
        });
        if (response.ok) {
            const newPost = await response.json();
            posts.push(newPost);
            currentIndex = posts.length - 1; // Показуємо новий пост
            renderCurrentPost();
            createPostForm.reset();
        } else {
            alert("Не вдалося створити пост");
        }
    } catch (error) {
        console.error("Помилка створення поста:", error);
    }
});

// Ініціалізація додатку
(async function startApp() {
    await fetchPosts();
    renderCurrentPost();
})();
